={{ (() => {
  const mensajeOriginal = $fromAI('mensaje_original', 'Copia LITERAL y completa, palabra por palabra, la parte del mensaje del usuario donde menciona el identificador del animal (arete, número de fuego o RFID). No resumas, no reescribas, no interpretes — pega el texto tal cual.', 'string') || '';
  const soloDigitos = mensajeOriginal.replace(/\s+/g, '');
  const corridas = soloDigitos.match(/\d{6,}/g) || [];
  const identificadorDeterministico = corridas.length === 1 ? corridas[0] : null;

  return [
    identificadorDeterministico || $fromAI('identificador', 'El identificador del animal (arete SINIIGA o número de fuego o RFID/electronic_rfid — chip o bolo ruminal). Usa el valor que el usuario haya proporcionado', 'string'),
    $fromAI('tenant_id', 'ID del rancho / tenant_id actual del usuario', 'number'),
    $fromAI('user_email', 'Copia el email del usuario EXACTAMENTE carácter por carácter desde el contexto de sesión (system prompt) — nunca lo reescribas de memoria ni lo abrevies. Antes de usarlo, cuenta que tenga el mismo número de caracteres que el original. Un solo carácter de diferencia hace que el sistema no encuentre ningún dato, sin mostrar ningún error.', 'string')
  ];
})() }}

